select PI.name as Name, PI.StackCount, PI.rarity as Rarity, PI.levelrequirement as LevelRequirement, PI.baserecord as BaseRecord, PI.prefixrecord as PrefixRecord, PI.suffixrecord as SuffixRecord, PI.ModifierRecord as ModifierRecord, PI.MateriaRecord as MateriaRecord, PI.AscendantAffixNameRecord as AscendantAffixNameRecord, PI.AscendantAffix2hNameRecord as AscendantAffix2hNameRecord, PI.PrefixRarity as PrefixRarity, PI.cloudid as CloudId, PI.cloud_hassync as IsCloudSynchronizedValue, PI.Id as Id, PI.Mod as Mod, CAST(PI.IsHardcore as bit) as IsHardcore, IFNULL(RerollsUsed, 0) as RerollsUsed, IFNULL(AffixRerollsUsed, 0) as AffixRerollsUsed, '' AS PetRecord, '[]' AS ReplicaInfo, PI.Seed as Seed FROM PlayerItem PI LEFT OUTER JOIN ReplicaItem2 R ON PI.ID = R.playeritemid WHERE (PI.Mod IS NULL OR PI.Mod = '') AND NOT PI.IsHardcore AND PI.LevelRequirement <= :maxlevel ORDER BY PI.levelrequirement, PI.name, PI.Id LIMIT 1001 OFFSET 0
